// 內建 3D 範本「Screen in a scene」（spec §5.8）：螢幕播當格畫面（V1），放在三種程式畫的場景裡：
//   desk（木紋桌上的螢幕）、classroom（教室黑板，影片就是板面）、studio（攝影棚，螢幕立在架上、聚光）。
// 場景全部用程式畫（沒有外部素材，開發者 2026-10-27 決定）；桌上螢幕移植自 spikes/export-bench/src/scene3d.ts。
// 三個場景的螢幕位置、大小相同，運鏡共用。頭尾接回滿版：區段開頭與結尾鏡頭正對螢幕、螢幕剛好填滿畫面。
// 鏡頭：有鏡頭關鍵幀（env.params.cameraKeys，前面串了 cameraPath.js 的 CAMERA3D）就照關鍵幀走，否則用 motion 預設運鏡。
// 參數：scene、motion（reveal 拉遠再推回／push 慢慢推近／orbit 繞半圈）、tilt（螢幕後仰度數）、ramp（頭尾過場秒數）。
/* global CAMERA3D */

/** 畫面只由 t 決定（跳格不必從頭推） */
const pure = true;

/** 螢幕寬高（場景單位）與中心高度 */
const SCREEN_W = 4.0;
const SCREEN_H = SCREEN_W * 9 / 16;
const CENTER_Y = 1.25;

/** 場景物件（setup 建、update 用） */
const S = {};

/** 木紋程序貼圖：幾個頻率的正弦疊成年輪＋固定偽雜訊（每次都一樣）；tone 調深淺 */
function woodTexture(THREE, tone) {
  const size = 256;
  const data = new Uint8Array(size * size * 4);
  for (let y = 0; y < size; y++) {
    const ring = Math.sin(y * 0.21) * 0.5 + Math.sin(y * 0.047 + 1.3) * 0.35 + Math.sin(y * 0.9) * 0.15;
    for (let x = 0; x < size; x++) {
      const noise = ((x * 7919 + y * 104729) % 97) / 97 - 0.5;
      const k = (0.62 + ring * 0.16 + noise * 0.05) * tone;
      const i = (y * size + x) * 4;
      data[i] = Math.min(255, 168 * k + 20);
      data[i + 1] = Math.min(255, 112 * k + 12);
      data[i + 2] = Math.min(255, 66 * k + 8);
      data[i + 3] = 255;
    }
  }
  const tex = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(4, 3);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.generateMipmaps = true;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.needsUpdate = true;
  return tex;
}

/** 垂直漸層貼圖（攝影棚背景） */
function gradientTexture(THREE, top, bottom) {
  const c = new OffscreenCanvas(4, 256);
  const g = c.getContext('2d');
  const grad = g.createLinearGradient(0, 0, 0, 256);
  grad.addColorStop(0, top);
  grad.addColorStop(1, bottom);
  g.fillStyle = grad;
  g.fillRect(0, 0, 4, 256);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

/** 木紋桌：桌面、螢幕邊框與底座、桌上的方塊和杯子 */
function buildDesk(THREE, scene, group) {
  scene.background = new THREE.Color(0x1a1410);
  const desk = new THREE.Mesh(new THREE.PlaneGeometry(26, 16), new THREE.MeshStandardMaterial({ map: woodTexture(THREE, 1), roughness: 0.75 }));
  desk.rotation.x = -Math.PI / 2;
  scene.add(desk);
  group.add(new THREE.Mesh(new THREE.BoxGeometry(SCREEN_W + 0.22, SCREEN_H + 0.22, 0.1), new THREE.MeshStandardMaterial({ color: 0x15171c, roughness: 0.4, metalness: 0.3 })));
  const stand = new THREE.MeshStandardMaterial({ color: 0x2a2d35, roughness: 0.5, metalness: 0.4 });
  const neck = new THREE.Mesh(new THREE.BoxGeometry(0.35, 1.2, 0.12), stand);
  neck.position.set(0, -0.95, -0.1);
  group.add(neck);
  const base = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.06, 1.0), stand);
  base.position.set(0, 0.03, 0.15);
  scene.add(base);
  const block = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.5, 0.7), new THREE.MeshStandardMaterial({ color: 0x3b7ddd, roughness: 0.6 }));
  block.position.set(-3.2, 0.25, 1.2);
  block.rotation.y = 0.5;
  scene.add(block);
  const cup = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.24, 0.6, 32), new THREE.MeshStandardMaterial({ color: 0xe9e6df, roughness: 0.3 }));
  cup.position.set(3.1, 0.3, 1.6);
  scene.add(cup);
}

/** 教室：牆、木地板、黑板邊框與粉筆槽（影片就是板面）、講桌 */
function buildClassroom(THREE, scene, group) {
  scene.background = new THREE.Color(0xd9d2c3);
  const wall = new THREE.Mesh(new THREE.PlaneGeometry(30, 12), new THREE.MeshStandardMaterial({ color: 0xe8e0cf, roughness: 0.95 }));
  wall.position.set(0, 4, -0.3);
  scene.add(wall);
  const floor = new THREE.Mesh(new THREE.PlaneGeometry(30, 16), new THREE.MeshStandardMaterial({ map: woodTexture(THREE, 0.75), roughness: 0.8 }));
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = -0.6;
  scene.add(floor);
  // 黑板木框（比螢幕大一圈）與粉筆槽
  const frame = new THREE.MeshStandardMaterial({ color: 0x6b4a2b, roughness: 0.7 });
  group.add(new THREE.Mesh(new THREE.BoxGeometry(SCREEN_W + 0.5, SCREEN_H + 0.5, 0.08), frame));
  const tray = new THREE.Mesh(new THREE.BoxGeometry(SCREEN_W + 0.5, 0.08, 0.25), frame);
  tray.position.set(0, -SCREEN_H / 2 - 0.28, 0.12);
  group.add(tray);
  for (let i = 0; i < 3; i++) {
    const chalk = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 0.22, 10), new THREE.MeshStandardMaterial({ color: [0xffffff, 0xf7e27a, 0xf2a3b3][i], roughness: 0.9 }));
    chalk.rotation.z = Math.PI / 2;
    chalk.position.set(-1.2 + i * 0.35, -SCREEN_H / 2 - 0.2, 0.15);
    group.add(chalk);
  }
  // 講桌
  const lectern = new THREE.Mesh(new THREE.BoxGeometry(1.6, 1.1, 0.8), frame);
  lectern.position.set(2.8, -0.05, 2.2);
  scene.add(lectern);
}

/** 攝影棚：漸層背幕、地面、螢幕立架、兩盞聚光的光錐 */
function buildStudio(THREE, scene, group) {
  scene.background = new THREE.Color(0x101318);
  const backdrop = new THREE.Mesh(new THREE.PlaneGeometry(40, 16), new THREE.MeshBasicMaterial({ map: gradientTexture(THREE, '#2c3240', '#0d0f14') }));
  backdrop.position.set(0, 4, -6);
  scene.add(backdrop);
  const floor = new THREE.Mesh(new THREE.PlaneGeometry(40, 20), new THREE.MeshStandardMaterial({ color: 0x1b1f27, roughness: 0.35, metalness: 0.2 }));
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = -0.6;
  scene.add(floor);
  group.add(new THREE.Mesh(new THREE.BoxGeometry(SCREEN_W + 0.14, SCREEN_H + 0.14, 0.08), new THREE.MeshStandardMaterial({ color: 0x0b0c10, roughness: 0.3, metalness: 0.5 })));
  // 立架：從螢幕下緣到地面（沒有環境貼圖，金屬感調低免得暗掉），底下一塊圓底座
  const steel = new THREE.MeshStandardMaterial({ color: 0x9aa3b2, metalness: 0.3, roughness: 0.4 });
  const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 1.8, 16), steel);
  pole.position.set(0, -0.6 + 0.9 - CENTER_Y, -0.1);
  group.add(pole);
  const foot = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.7, 0.05, 32), steel);
  foot.position.set(0, -0.575, 0);
  scene.add(foot);
  for (const x of [-4.5, 4.5]) {
    const cone = new THREE.Mesh(new THREE.ConeGeometry(1.8, 7, 32, 1, true), new THREE.MeshBasicMaterial({ color: 0xfff3d6, transparent: true, opacity: 0.07, side: THREE.DoubleSide, depthWrite: false }));
    cone.position.set(x, 3, -1);
    cone.rotation.z = x < 0 ? -0.35 : 0.35;
    scene.add(cone);
  }
}

/** 建場景 */
function setup(THREE, scene, camera, env) {
  scene.add(new THREE.AmbientLight(0xffffff, 1.1));
  const sun = new THREE.DirectionalLight(0xfff1dd, 2.2);
  sun.position.set(-4, 8, 6);
  scene.add(sun);

  const tilt = -(env.params.tilt ?? 7) * Math.PI / 180;
  const group = new THREE.Group();
  group.position.set(0, CENTER_Y, 0);
  group.rotation.x = tilt;
  scene.add(group);
  const kind = env.params.scene || 'desk';
  if (kind === 'classroom') buildClassroom(THREE, scene, group);
  else if (kind === 'studio') buildStudio(THREE, scene, group);
  else buildDesk(THREE, scene, group);
  const screen = new THREE.Mesh(new THREE.PlaneGeometry(SCREEN_W, SCREEN_H), env.frameMaterial());
  screen.position.z = 0.056;
  group.add(screen);

  // 滿版位置：正對螢幕、沿螢幕法線退到剛好填滿畫面的距離（畫面比螢幕寬時以高度為準）
  S.fov0 = camera.fov;
  const fov = camera.fov * Math.PI / 180;
  const aspect = env.width / env.height;
  const dist = Math.max(SCREEN_H / 2, SCREEN_W / 2 / aspect) / Math.tan(fov / 2) + 0.056;
  const normal = new THREE.Vector3(0, 0, 1).applyAxisAngle(new THREE.Vector3(1, 0, 0), tilt);
  const center = new THREE.Vector3(0, CENTER_Y, 0).add(normal.clone().multiplyScalar(0.056));
  S.THREE = THREE;
  S.camera = camera;
  S.flat = { pos: center.clone().add(normal.clone().multiplyScalar(dist - 0.056)), look: center.clone(), up: new THREE.Vector3(0, 1, 0).applyAxisAngle(new THREE.Vector3(1, 0, 0), tilt), fov: camera.fov };
}

/** 平滑（頭尾慢、中間快） */
function smooth(u) {
  const x = Math.min(1, Math.max(0, u));
  return x * x * (3 - 2 * x);
}

/** 預設運鏡的中間段（u：0～1） */
function presetCamera(THREE, motion, u) {
  const look = new THREE.Vector3(0, CENTER_Y * 0.8, 0);
  if (motion === 'orbit') {
    const a = -0.8 + u * 1.6;
    return { pos: new THREE.Vector3(Math.sin(a) * 9, 4.2, Math.cos(a) * 9), look, fov: S.fov0 };
  }
  if (motion === 'push') return { pos: new THREE.Vector3(0.8 - u * 0.8, 3.6 - u * 1.2, 10 - u * 3.5), look, fov: S.fov0 };
  return { pos: new THREE.Vector3(-1.2 + u * 2.4, 4.4, 9.5), look, fov: S.fov0 };
}

/** 中間段在時間 t 的鏡頭：有關鍵幀照關鍵幀，否則預設運鏡 */
function middleCamera(THREE, env, t, ramp) {
  const keys = env.params.cameraKeys;
  if (keys && keys.length) {
    const c = CAMERA3D.cameraAt(keys, t);
    return { pos: new THREE.Vector3(...c.position), look: new THREE.Vector3(...c.target), fov: c.fov };
  }
  const L = env.duration;
  return presetCamera(THREE, env.params.motion || 'reveal', L > 2 * ramp ? (t - ramp) / (L - 2 * ramp) : 0.5);
}

/** 每格更新鏡頭：頭尾在滿版與中間段之間過場 */
function update(t, env) {
  const THREE = S.THREE;
  const camera = S.camera;
  const L = env.duration;
  const ramp = Math.min(env.params.ramp ?? 1.2, L / 3);
  let k = 1;
  let target;
  if (t < ramp) { k = smooth(t / ramp); target = middleCamera(THREE, env, ramp, ramp); }
  else if (t > L - ramp) { k = smooth((L - t) / ramp); target = middleCamera(THREE, env, L - ramp, ramp); }
  else target = middleCamera(THREE, env, t, ramp);
  camera.position.copy(S.flat.pos).lerp(target.pos, k);
  camera.up.copy(S.flat.up).lerp(new THREE.Vector3(0, 1, 0), k).normalize();
  camera.lookAt(S.flat.look.clone().lerp(target.look, k));
  camera.fov = S.flat.fov + (target.fov - S.flat.fov) * k;
  camera.updateProjectionMatrix();
}

// 內建 3D 範本「Mascot」（spec §5.7、§5.8 吉祥物）：基本幾何組成的小角色，疊在影片上（anim3d，透明背景）。
// 從畫面一側走進來，停在目標框旁邊，然後揮手或指著目標框；目標框 env.box（0～1）可以在預覽上拖。
// 畫面只由 t 決定（pure）；鏡頭固定，畫面座標用 z=0 平面換算（box 的位置對得上畫面）。
// 參數：action（wave 揮手／point 指著框）、from（left／right 從哪邊走進來）、color、height（角色高度佔畫面高的比例）、walk（走路秒數）。

/** 畫面只由 t 決定 */
const pure = true;

/** 場景物件 */
const M = {};

/** 建角色：身體、頭、眼睛、手腳（每個關節一個 Group，方便轉） */
function buildMascot(THREE, color) {
  const body = new THREE.MeshStandardMaterial({ color, roughness: 0.45, metalness: 0.05 });
  const dark = new THREE.MeshStandardMaterial({ color: 0x1b1d24, roughness: 0.6 });
  const white = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.3 });
  const root = new THREE.Group();

  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.42, 0.55, 8, 16), body);
  torso.position.y = 1.15;
  root.add(torso);
  const head = new THREE.Group();
  head.position.y = 2.05;
  head.add(new THREE.Mesh(new THREE.SphereGeometry(0.48, 24, 16), body));
  for (const side of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.12, 16, 12), white);
    eye.position.set(0.17 * side, 0.06, 0.4);
    head.add(eye);
    const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.06, 12, 8), dark);
    pupil.position.set(0.17 * side, 0.06, 0.5);
    head.add(pupil);
  }
  root.add(head);

  /** 一條手或腳：肩（髖）關節 Group，裡面一根膠囊往下垂 */
  const limb = (x, y, len, radius) => {
    const joint = new THREE.Group();
    joint.position.set(x, y, 0);
    const m = new THREE.Mesh(new THREE.CapsuleGeometry(radius, len, 6, 12), body);
    m.position.y = -len / 2 - radius;
    joint.add(m);
    root.add(joint);
    return joint;
  };
  return {
    root, head,
    armL: limb(-0.52, 1.5, 0.55, 0.12), armR: limb(0.52, 1.5, 0.55, 0.12),
    legL: limb(-0.2, 0.68, 0.42, 0.14), legR: limb(0.2, 0.68, 0.42, 0.14),
  };
}

/** 建場景 */
function setup(THREE, scene, camera, env) {
  scene.add(new THREE.AmbientLight(0xffffff, 1.3));
  const key = new THREE.DirectionalLight(0xffffff, 2.2);
  key.position.set(3, 6, 8);
  scene.add(key);
  camera.position.set(0, 0, 20);
  camera.lookAt(0, 0, 0);
  camera.updateProjectionMatrix();
  // z=0 平面上看得到的範圍（畫面座標換算用）
  M.viewH = 2 * 20 * Math.tan(camera.fov * Math.PI / 360);
  M.viewW = M.viewH * camera.aspect;
  M.parts = buildMascot(THREE, new THREE.Color(env.params.color || '#ffb020'));
  scene.add(M.parts.root);
}

/** 畫面座標（0～1，y 往下）→ z=0 平面的世界座標 */
function toWorld(x, y) {
  return { x: (x - 0.5) * M.viewW, y: (0.5 - y) * M.viewH };
}

/** 平滑（頭尾慢） */
function smooth(u) {
  const x = Math.min(1, Math.max(0, u));
  return x * x * (3 - 2 * x);
}

/** 每格：走路 → 停在框旁 → 揮手或指著框 */
function update(t, env) {
  const p = env.params;
  const box = env.box || { cx: 0.5, cy: 0.5, w: 0.3, h: 0.2 };
  const P = M.parts;
  const fromLeft = (p.from || 'left') === 'left';
  const size = (p.height ?? 0.35) * M.viewH / 2.6;  // 角色模型高約 2.6
  P.root.scale.setScalar(size);

  // 站的位置：框靠近入場那一側的外面，腳底對齊框的下緣（畫面外就夾回來）
  const standX = Math.min(0.92, Math.max(0.08, fromLeft ? box.cx - box.w / 2 - 0.07 : box.cx + box.w / 2 + 0.07));
  const footY = Math.min(0.98, box.cy + box.h / 2);
  const start = toWorld(fromLeft ? -0.12 : 1.12, footY);
  const stand = toWorld(standX, footY);
  const walk = Math.min(p.walk ?? 1.6, env.duration * 0.6);
  const k = smooth(t / walk);
  P.root.position.set(start.x + (stand.x - start.x) * k, stand.y, 0);

  // 走路：腳前後擺、身體上下彈，面向前進方向；到了就轉正面向鏡頭
  const walking = t < walk;
  const phase = t * 9;
  const swing = walking ? Math.sin(phase) * 0.7 : 0;
  P.legL.rotation.x = swing;
  P.legR.rotation.x = -swing;
  P.root.rotation.y = walking ? (fromLeft ? 1 : -1) * 0.9 * (1 - smooth((t - walk + 0.3) / 0.3)) : 0;
  P.root.position.y += walking ? Math.abs(Math.sin(phase)) * 0.08 * size : 0;

  // 手：走路時跟著擺；到了以後揮手（靠框那隻手舉高左右揮）或指著框中心
  const near = fromLeft ? P.armR : P.armL;
  const far = fromLeft ? P.armL : P.armR;
  if (walking) {
    near.rotation.set(-swing * 0.8, 0, 0);
    far.rotation.set(swing * 0.8, 0, 0);
    P.head.rotation.z = 0;
  } else {
    const a = smooth((t - walk) / 0.35);
    far.rotation.set(0, 0, (fromLeft ? 1 : -1) * 0.15 * a);
    if ((p.action || 'point') === 'wave') {
      near.rotation.set(0, 0, (fromLeft ? 1 : -1) * (2.6 * a + Math.sin((t - walk) * 10) * 0.35 * a));
    } else {
      // 指向框中心：從肩膀到框中心的角度（手臂預設朝下，所以加 90°）
      const shoulder = P.root.localToWorld(near.position.clone());
      const target = toWorld(box.cx, box.cy);
      const angle = Math.atan2(target.y - shoulder.y, target.x - shoulder.x) + Math.PI / 2;
      near.rotation.set(0, 0, angle * a);
    }
    P.head.rotation.z = Math.sin((t - walk) * 2.2) * 0.06;
  }
}

// 內建 3D 插件「翻頁式片頭」（spec §5.23、D34；節奏與畫面參數取自 brand-v2 短版，調查 docs/research/intro-styles.md §1.4～§1.5）。
// 全畫面（scene3d）：封面一張張以上緣為軸翻下、越翻越快、舞台推近微轉 → 一次閃光 → 標題方塊縮入、字裡輪流透出封面 → 揭曉轉白字＋彈跳＋斜光 → 結尾淡出。
// 時間表由主程式的 intro/flip.ts 算好放在參數裡（畫面與音效同一份），插件只依 t 畫，所以 pure。
// 參數（env.params）：
//   imageIds（主程式解碼成 env.images，順序相同）、pages [{t, img, strength}]（img 是 env.images 的索引）、titleFills [索引]、icon（索引或 null）、
//   montageStart、titleIn、flash、reveal（秒）、title、subtitle、tone（duotone｜original）、dark、light（雙色調的暗色與亮色）、accent（標題方塊顏色）。
// 圖片貼圖不做色彩轉換（同 frameMaterial），ImageBitmap 第一列在最上，所以在 shader 翻 v。

/** 畫面只由 t 決定 */
const pure = true;

/** 場景物件 */
const F = {};

/** 頁面尺寸（世界單位；畫面高 1.08、鏡頭距離 1.8 時剛好是 brand-v2 的 1600×900 頁面在 1920×1080 舞台） */
const PAGE_W = 1.6;
const PAGE_H = 0.9;
/** 舞台原點到鏡頭的距離（垂直視角 33.4° 時畫面高 1.08） */
const CAM_D = 1.8;

/** GSAP 的 power 系列緩動 */
const easeIn = (p, n) => Math.pow(p, n + 1);
const easeOut = (p, n) => 1 - Math.pow(1 - p, n + 1);
const clamp01 = (x) => Math.max(0, Math.min(1, x));

/** #rrggbb → [r, g, b]（0～1，不做色彩轉換） */
function rgb(hex, fallback) {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex || '') || /^#?([0-9a-f]{6})$/i.exec(fallback);
  const n = parseInt(m[1], 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

/** 貼圖（ImageBitmap 或畫布）：不翻轉、不轉色彩、不做 mipmap */
function rawTexture(THREE, image, Ctor) {
  const tex = new (Ctor || THREE.Texture)(image);
  tex.flipY = false;
  tex.colorSpace = THREE.NoColorSpace;
  tex.generateMipmaps = false;
  tex.minFilter = THREE.LinearFilter;
  tex.magFilter = THREE.LinearFilter;
  tex.needsUpdate = true;
  return tex;
}

/** 貼圖材質：可選雙色調（依亮度在 dark、light 之間上色）、整體透明度 */
function pageMaterial(THREE, tex, duo, dark, light) {
  return new THREE.ShaderMaterial({
    transparent: true,
    uniforms: { map: { value: tex }, duo: { value: duo }, dark: { value: new THREE.Vector3(...dark) }, light: { value: new THREE.Vector3(...light) }, opacity: { value: 1 } },
    vertexShader: 'varying vec2 vUv; void main() { vUv = vec2(uv.x, 1.0 - uv.y); gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
    fragmentShader: [
      'uniform sampler2D map; uniform float duo; uniform vec3 dark; uniform vec3 light; uniform float opacity; varying vec2 vUv;',
      'void main() {',
      '  vec4 c = texture2D(map, vUv);',
      '  float l = dot(c.rgb, vec3(0.299, 0.587, 0.114));',
      '  vec3 d = mix(dark, light, smoothstep(0.05, 0.95, l));',
      '  gl_FragColor = vec4(mix(c.rgb, d, duo), c.a * opacity);',
      '}',
    ].join('\n'),
  });
}

/** 依 cover 方式把圖片畫進框（裁掉多的） */
function drawCover(g, img, x, y, w, h) {
  const s = Math.max(w / img.width, h / img.height);
  const sw = w / s;
  const sh = h / s;
  g.drawImage(img, (img.width - sw) / 2, (img.height - sh) / 2, sw, sh, x, y, w, h);
}

/** 圓角矩形路徑 */
function roundRect(g, x, y, w, h, r) {
  g.beginPath();
  g.moveTo(x + r, y);
  g.arcTo(x + w, y, x + w, y + h, r);
  g.arcTo(x + w, y + h, x, y + h, r);
  g.arcTo(x, y + h, x, y, r);
  g.arcTo(x, y, x + w, y, r);
  g.closePath();
}

/** 建場景 */
function setup(THREE, scene, camera, env) {
  const p = env.params;
  const { width: w, height: h } = env;
  camera.fov = 2 * Math.atan(540 / 1800) * 180 / Math.PI;
  camera.aspect = w / h;
  camera.position.set(0, 0, CAM_D);
  camera.lookAt(0, 0, 0);
  camera.updateProjectionMatrix();
  scene.add(camera);
  F.dark = rgb(p.dark, '#141a4a');
  F.light = rgb(p.light, '#a9b8ff');

  // 背景：遠處一片暗色漸層（全畫面不透明，蓋住 V1）
  const bgCanvas = new OffscreenCanvas(64, 36);
  const bg = bgCanvas.getContext('2d');
  const grad = bg.createRadialGradient(32, 14, 0, 32, 14, 48);
  grad.addColorStop(0, '#20264f');
  grad.addColorStop(1, '#05060d');
  bg.fillStyle = grad;
  bg.fillRect(0, 0, 64, 36);
  const far = 40;
  const fh = 2 * (far + CAM_D) * Math.tan(camera.fov * Math.PI / 360) * 1.6;
  const bgMesh = new THREE.Mesh(new THREE.PlaneGeometry(fh * w / h, fh), pageMaterial(THREE, rawTexture(THREE, bgCanvas, THREE.CanvasTexture), 0, F.dark, F.light));
  bgMesh.position.z = -far;
  scene.add(bgMesh);

  // 舞台與頁面：幾何往下平移半頁，原點在上緣（翻頁以上緣為軸）
  F.stage = new THREE.Group();
  scene.add(F.stage);
  const textures = (env.images || []).map((b) => rawTexture(THREE, b));
  const geo = new THREE.PlaneGeometry(PAGE_W, PAGE_H);
  geo.translate(0, -PAGE_H / 2, 0);
  const duo = p.tone === 'original' ? 0 : 1;
  F.pages = (p.pages || []).map((page, i) => {
    const tex = textures[page.img] || textures[0];
    const mesh = new THREE.Mesh(geo, tex ? pageMaterial(THREE, tex, duo, F.dark, F.light) : new THREE.MeshBasicMaterial({ color: 0x333a66 }));
    mesh.position.set(0, PAGE_H / 2, i * 0.002);
    mesh.visible = false;
    F.stage.add(mesh);
    const next = (p.pages[i + 1] || {}).t;
    const gap = next !== undefined ? next - page.t : (i > 0 ? page.t - p.pages[i - 1].t : 0.2);
    return { mesh, t: page.t, dur: Math.min(0.55, gap * 1.5) };
  });

  // 鏡頭前的兩片：標題卡（畫在畫布上）與閃光
  const dist = 1;
  const vh = 2 * dist * Math.tan(camera.fov * Math.PI / 360);
  F.cardCanvas = new OffscreenCanvas(w, h);
  F.card = F.cardCanvas.getContext('2d');
  F.cardTex = rawTexture(THREE, F.cardCanvas, THREE.CanvasTexture);
  F.cardMesh = new THREE.Mesh(new THREE.PlaneGeometry(vh * w / h, vh), pageMaterial(THREE, F.cardTex, 0, F.dark, F.light));
  F.cardMesh.position.z = -dist;
  F.cardMesh.renderOrder = 10;
  F.cardMesh.material.depthTest = false;
  camera.add(F.cardMesh);
  F.flash = new THREE.Mesh(new THREE.PlaneGeometry(vh * w / h * 1.1, vh * 1.1), new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, depthTest: false }));
  F.flash.position.z = -dist * 0.9;
  F.flash.renderOrder = 11;
  camera.add(F.flash);
  // 標題的另一張畫布：先畫字、再用 source-in 把封面填進字裡
  F.textCanvas = new OffscreenCanvas(w, h);
  F.text = F.textCanvas.getContext('2d');
  F.camera = camera;
}

/** 畫標題卡（t ≥ titleIn） */
function drawCard(t, env) {
  const p = env.params;
  const g = F.card;
  const w = env.width;
  const h = env.height;
  g.clearRect(0, 0, w, h);
  if (t < p.titleIn) return;
  const imgs = env.images || [];
  const title = String(p.title || '');
  const fs = h * 0.13;
  const font = `900 ${fs}px "Segoe UI", "Helvetica Neue", Arial, sans-serif`;
  g.font = font;
  const tw = Math.min(g.measureText(title).width, w * 0.7);
  const bw = tw + fs * 1.2;
  const bh = fs * 1.6;
  const revealed = t >= p.reveal;
  // 方塊：從 1.22 倍縮入（0.4 秒 power3.out）；揭曉時彈 1.04 倍
  let scale = 1.22 - 0.22 * easeOut(clamp01((t - p.titleIn) / 0.4), 3);
  if (revealed && t < p.reveal + 0.25) scale *= 1 + 0.04 * Math.sin(Math.PI * (t - p.reveal) / 0.25);
  g.save();
  g.translate(w / 2, h / 2);
  g.scale(scale, scale);
  g.globalAlpha = clamp01((t - p.titleIn) / 0.08);
  const accent = rgb(p.accent, '#2f5bff').map((c) => Math.round(c * 255 * (revealed ? 1 : 0.62)));
  g.fillStyle = `rgb(${accent.join(',')})`;
  roundRect(g, -bw / 2, -bh / 2, bw, bh, fs * 0.18);
  g.fill();
  // 字：揭曉前每 2 格換一張封面透出，揭曉後白字
  const tx = F.text;
  tx.setTransform(1, 0, 0, 1, 0, 0);
  tx.clearRect(0, 0, w, h);
  tx.font = font;
  tx.textAlign = 'center';
  tx.textBaseline = 'middle';
  tx.fillStyle = '#ffffff';
  tx.fillText(title, w / 2, h / 2 + fs * 0.04, w * 0.7);
  const fills = p.titleFills || [];
  if (!revealed && fills.length && imgs.length) {
    const k = Math.floor((t - p.titleIn) * env.fps / 2) % fills.length;
    const img = imgs[fills[k]] || imgs[0];
    tx.globalCompositeOperation = 'source-in';
    drawCover(tx, img, w / 2 - bw / 2, h / 2 - bh / 2, bw, bh);
    tx.globalCompositeOperation = 'source-over';
  }
  g.drawImage(F.textCanvas, -w / 2, -h / 2);
  // icon：揭曉後彈入，放在方塊左邊
  const icon = p.icon === null || p.icon === undefined ? null : imgs[p.icon];
  if (icon && t >= p.reveal + 0.05) {
    const q = clamp01((t - p.reveal - 0.05) / 0.25);
    const s = q < 0.6 ? 1.1 * easeOut(q / 0.6, 2) : 1.1 - 0.1 * easeOut((q - 0.6) / 0.4, 1);
    const size = bh * s;
    g.save();
    g.translate(-bw / 2 - bh * 0.7, 0);
    roundRect(g, -size / 2, -size / 2, size, size, size * 0.2);
    g.clip();
    drawCover(g, icon, -size / 2, -size / 2, size, size);
    g.restore();
  }
  // 斜光：揭曉後 0.6 秒掃過方塊（只亮在已畫的地方）
  const sweep = (t - p.reveal - 0.6) / 0.5;
  if (sweep > 0 && sweep < 1) {
    g.globalCompositeOperation = 'source-atop';
    const x = -bw / 2 - bh + (bw + bh * 2) * sweep;
    const lg = g.createLinearGradient(x - bh * 0.5, 0, x + bh * 0.5, 0);
    lg.addColorStop(0, 'rgba(255,255,255,0)');
    lg.addColorStop(0.5, 'rgba(255,255,255,0.55)');
    lg.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = lg;
    g.fillRect(-bw, -bh, bw * 2, bh * 2);
    g.globalCompositeOperation = 'source-over';
  }
  g.restore();
  // 副標：揭曉後逐字出現（每字 0.04 秒）
  const sub = String(p.subtitle || '');
  if (sub && t >= p.reveal + 0.15) {
    const n = Math.min(sub.length, Math.floor((t - p.reveal - 0.15) / 0.04) + 1);
    g.font = `600 ${fs * 0.36}px "Segoe UI", "Helvetica Neue", Arial, sans-serif`;
    g.textAlign = 'center';
    g.textBaseline = 'top';
    g.fillStyle = 'rgba(255,255,255,0.88)';
    g.fillText(sub.slice(0, n), w / 2, h / 2 + bh * 0.5 * scale + fs * 0.35, w * 0.8);
  }
}

/** 每格更新 */
function update(t, env) {
  const p = env.params;
  const start = p.montageStart || 0;
  const climax = p.titleIn;
  // 舞台推近微轉：scale 0.72→1.32（鏡頭距離反比）、rotationY −10°→8°、rotationX 6°→−2°，power1.in
  const m = easeIn(clamp01((t - start) / Math.max(0.01, climax - start)), 1);
  const s = 0.72 + 0.6 * m;
  F.camera.position.set(0, 0, CAM_D / s);
  F.stage.rotation.y = (-10 + 18 * m) * Math.PI / 180;
  F.stage.rotation.x = (6 - 8 * m) * Math.PI / 180;
  // 頁面：到時間就整頁不透明（不漸變，避免兩頁半透明疊在一起），從 −105° 翻到 0°（power2.out）；標題進場後收掉
  for (const page of F.pages) {
    const on = t >= page.t && t < climax;
    page.mesh.visible = on;
    if (on) page.mesh.rotation.x = -105 * (1 - easeOut(clamp01((t - page.t) / page.dur), 2)) * Math.PI / 180;
  }
  // 閃光：0.06 秒升到 0.85，0.35 秒退
  const f = t - p.flash;
  F.flash.material.opacity = f < 0 ? 0 : f < 0.06 ? 0.85 * f / 0.06 : Math.max(0, 0.85 * (1 - (f - 0.06) / 0.35));
  drawCard(t, env);
  F.cardTex.needsUpdate = true;
  // 結尾 0.35 秒淡出到背景
  F.cardMesh.material.uniforms.opacity.value = clamp01((env.duration - t) / 0.35);
}
